mapper.select:
SELECT app_id, open_id, name, avatar_url
FROM news_feishu_authorized_user
WHERE app_id = #{appId} AND open_id = #{openId}

mapper.insert:
INSERT INTO news_feishu_authorized_user (app_id, open_id, name, avatar_url)
VALUES (#{appId}, #{openId}, #{name}, #{avatarUrl})
ON DUPLICATE KEY UPDATE name = #{name}, avatar_url = #{avatarUrl}
